-- A22: histórico interno de inventário; não representa disponibilidade, reserva, venda, cliente, contrato ou financeiro.
alter table public.subdivision_lot_inventory_states add constraint subdivision_lot_inventory_states_tenant_match unique (id, organization_id);
create table public.subdivision_lot_inventory_events (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,inventory_state_id uuid not null,from_phase public.subdivision_lot_inventory_phase not null,to_phase public.subdivision_lot_inventory_phase not null,created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_lot_inventory_events_state_fk foreign key(inventory_state_id,organization_id) references public.subdivision_lot_inventory_states(id,organization_id) on delete restrict,constraint subdivision_lot_inventory_events_change check(from_phase<>to_phase));
alter table public.subdivision_lot_inventory_events enable row level security;revoke all on table public.subdivision_lot_inventory_events from public,anon,authenticated;
comment on table public.subdivision_lot_inventory_events is 'A22: eventos internos de transição de inventário, sem disponibilidade, reserva, venda, cliente, contrato ou financeiro.';
create or replace function public.subdivision_transition_draft_lot_inventory_state(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_inventory_state_id uuid,p_to_phase public.subdivision_lot_inventory_phase,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_from public.subdivision_lot_inventory_phase;v_event uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_transition_draft_lot_inventory_state' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;select inventory_phase into v_from from public.subdivision_lot_inventory_states where id=p_inventory_state_id and organization_id=p_organization_id;if v_from is null or v_from=p_to_phase then raise exception using errcode='42501',message='SUBDIVISION_INVENTORY_TRANSITION_DENIED';end if;update public.subdivision_lot_inventory_states set inventory_phase=p_to_phase,updated_at=now(),created_by=p_actor_user_id where id=p_inventory_state_id and organization_id=p_organization_id;insert into public.subdivision_lot_inventory_events(organization_id,inventory_state_id,from_phase,to_phase,created_by)values(p_organization_id,p_inventory_state_id,v_from,p_to_phase,p_actor_user_id)returning id into v_event;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_transition_draft_lot_inventory_state','allowed','subdivision_lot_inventory_event',v_event,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'from_phase',v_from::text,'to_phase',p_to_phase::text));return v_event;end;$$;
revoke all on function public.subdivision_transition_draft_lot_inventory_state(uuid,uuid,public.operating_module,text,uuid,public.subdivision_lot_inventory_phase,uuid) from public,anon,authenticated;grant execute on function public.subdivision_transition_draft_lot_inventory_state(uuid,uuid,public.operating_module,text,uuid,public.subdivision_lot_inventory_phase,uuid) to service_role;
